const item = $input.first();

const invoice = item.json.parsed_invoice || {};
const items = Array.isArray(invoice.items) ? invoice.items : [];

const missingFields = [];

// ===== Campos obligatorios base =====
if (!invoice.emisor_nit) missingFields.push('emisor_nit');
if (!invoice.nro_factura) missingFields.push('nro_factura');
if (!invoice.codigo_autorizacion) missingFields.push('codigo_autorizacion');
if (!invoice.fecha_emision) missingFields.push('fecha_emision');
if (!invoice.cliente_nombre) missingFields.push('cliente_nombre');

if (invoice.total === null || invoice.total === undefined || Number.isNaN(Number(invoice.total))) {
  missingFields.push('total');
}

if (invoice.monto_a_pagar === null || invoice.monto_a_pagar === undefined || Number.isNaN(Number(invoice.monto_a_pagar))) {
  missingFields.push('monto_a_pagar');
}

// ===== Normalización numérica =====
const subtotal = Number(invoice.subtotal) || 0;
const total = Number(invoice.total) || 0;
const monto_pagar = Number(invoice.monto_a_pagar) || 0;

// ===== Validaciones de items =====
const items_count_detected = items.length;

const items_subtotal_sum = items.reduce((acc, it) => {
  return acc + (Number(it.subtotal) || 0);
}, 0);

const items_count_ok = items_count_detected > 0;

const items_completos_ok =
  items_count_ok &&
  items.every((it) =>
    it &&
    it.codigo &&
    it.descripcion &&
    it.cantidad !== null &&
    it.cantidad !== undefined &&
    it.unidad &&
    it.precio_unitario !== null &&
    it.precio_unitario !== undefined &&
    it.subtotal !== null &&
    it.subtotal !== undefined
  );

const items_vs_subtotal_ok =
  items_count_ok &&
  subtotal > 0 &&
  Math.abs(items_subtotal_sum - subtotal) < 1;

const total_vs_monto_ok =
  total > 0 &&
  monto_pagar > 0 &&
  Math.abs(total - monto_pagar) < 1;

const ticket_valido = invoice.ticket_valido === true;

// ===== Reglas de invalidación =====
if (!items_count_ok) {
  missingFields.push('items');
}

if (!items_completos_ok) {
  missingFields.push('items_incompletos');
}

if (!items_vs_subtotal_ok) {
  missingFields.push('items_inconsistentes');
}

if (!total_vs_monto_ok) {
  missingFields.push('total_inconsistente');
}

if (!ticket_valido) {
  missingFields.push('ticket_invalido');
}

// ===== Estado final =====
const quality_ok =
  items_count_ok &&
  items_completos_ok &&
  items_vs_subtotal_ok &&
  total_vs_monto_ok &&
  ticket_valido;

const isValid = missingFields.length === 0;

const validation = {
  is_valid: isValid,
  missing_fields: missingFields,
  validation_message: isValid
    ? 'Factura válida para continuar.'
    : `Faltan campos obligatorios: ${missingFields.join(', ')}`,

  items_subtotal_sum,
  items_vs_subtotal_ok,
  total_vs_monto_ok,
  items_count_detected,
  items_count_ok,
  items_completos_ok,
  ticket_valido,
  quality_ok,
};

return [
  {
    json: {
      ...item.json,
      validation,
    },
    binary: item.binary,
  },
];

const base = $('Code - Prepare IDs').first();

// Leer directamente las filas realmente encontradas en Google Sheets
const foundRows = $items('Get row(s) in Facturas', 0, 0) || [];
const firstFound = foundRows[0]?.json || null;

// Solo es duplicado si Get row(s) in Facturas devolvió al menos una fila real
const isDuplicateInvoice = foundRows.length > 0 && !!firstFound?.invoice_uid;

// Ya no usamos Procesamiento para detectar duplicado de archivo
const isDuplicateFile = false;

const duplicate = {
  ...(base.json.duplicate || {}),
  is_duplicate_file: isDuplicateFile,
  is_duplicate_invoice: isDuplicateInvoice,
  duplicate_type: isDuplicateInvoice ? 'duplicate_invoice' : null,
  duplicate_reason: isDuplicateInvoice ? 'invoice_uid' : null,
};

return [
  {
    json: {
      ...base.json,
      duplicate,
      debug_duplicate_check: {
        found_rows_count: foundRows.length,
        found_invoice_uid: firstFound?.invoice_uid || null,
      },
    },
    binary: base.binary,
  },
];

const item = $input.first();

const parsedInvoice = item.json.parsed_invoice || {};

const filename_original = item.json.filename_original || null;
const file_hash = item.json.file_hash || null;

const uploaded_by = item.json.uploaded_by || null;
const uploaded_by_name =
  item.json.uploaded_by_name ||
  item.json.uploaded_by ||
  null;

const sucursal_usuario = item.json.sucursal_usuario || null;
const punto_venta_usuario = item.json.punto_venta_usuario || null;

const ALLOWED_PAYMENT_METHODS = [
  'Efectivo',
  'QR',
  'Billetera Móvil',
  'Tarjeta',
  'Transferencia',
];

const ALLOWED_INCOME_STATUS = [
  'Ya ingresado',
  'Cuenta por cobrar',
];

const ALLOWED_LEVELS = [
  'Venta en tienda',
  'Empresa privada',
  'Empresa pública',
  'Institucional',
];

function normalizeOption(value, allowed, fallback) {
  const clean = String(value || '').trim();
  return allowed.includes(clean) ? clean : fallback;
}

function normalizePaymentMethod(value) {
  const clean = String(value || '').trim();

  return ALLOWED_PAYMENT_METHODS.includes(clean)
    ? clean
    : 'Efectivo';
}

const metodo_pago = normalizeOption(
  item.json.metodo_pago ||
  parsedInvoice.metodo_pago ||
  'Efectivo',
  ALLOWED_PAYMENT_METHODS,
  'Efectivo'
);

const estado_ingreso = normalizeOption(
  item.json.estado_ingreso ||
  parsedInvoice.estado_ingreso ||
  'Ya ingresado',
  ALLOWED_INCOME_STATUS,
  'Ya ingresado'
);

const fecha_estimada_ingreso = String(
  item.json.fecha_estimada_ingreso ||
  parsedInvoice.fecha_estimada_ingreso ||
  ''
).trim();

const nivel = normalizeOption(
  item.json.nivel ||
  parsedInvoice.nivel ||
  'Venta en tienda',
  ALLOWED_LEVELS,
  'Venta en tienda'
);

const fecha_ingreso_real =
  estado_ingreso === 'Ya ingresado'
    ? (parsedInvoice.fecha_iso || '')
    : '';

const now = new Date().toISOString();

function sanitize(value) {
  return String(value || '')
    .trim()
    .replace(/\s+/g, '_')
    .replace(/[^a-zA-Z0-9_\-]/g, '');
}

const emisorNitRaw = parsedInvoice.emisor_nit || null;
const nroFacturaRaw = parsedInvoice.nro_factura || null;
const codAutRaw =
  parsedInvoice.codigo_autorizacion ||
  parsedInvoice.cod_autorizacion ||
  null;

const emisorNit = emisorNitRaw ? sanitize(emisorNitRaw) : null;
const nroFactura = nroFacturaRaw ? sanitize(nroFacturaRaw) : null;
const codAut = codAutRaw ? sanitize(codAutRaw) : null;
const hashSafe = sanitize(file_hash || 'sin_hash');

const hasSafeKeys = !!(emisorNit && nroFactura && codAut);

// ID único de factura
const invoice_uid = hasSafeKeys
  ? `INV_${emisorNit}_${nroFactura}_${codAut}`
  : null;

// ID único de procesamiento
const process_id = `PROC_${Date.now()}_${hashSafe.slice(0, 12)}`;

const confidence_score = (
  parsedInvoice.emisor_nit &&
  parsedInvoice.nro_factura &&
  parsedInvoice.codigo_autorizacion &&
  parsedInvoice.total !== null &&
  parsedInvoice.total !== undefined &&
  parsedInvoice.items_count > 0 &&
  parsedInvoice.ticket_valido === true
) ? 0.95 : 0.60;

return [
  {
    json: {
      ...item.json,
      filename_original,
      file_hash,
      uploaded_by,
      uploaded_by_name,
      sucursal_usuario,
      punto_venta_usuario,
      metodo_pago,
      estado_ingreso,
      fecha_estimada_ingreso,
      fecha_ingreso_real,
      nivel,
      parsed_invoice: {
        ...parsedInvoice,
        metodo_pago,
        estado_ingreso,
        fecha_estimada_ingreso,
        fecha_ingreso_real,
        nivel,
      },
      invoice_uid,
      process_id,
      uploaded_at: now,
      processed_at: now,
      confidence_score,
      cod_autorizacion: codAutRaw,
      codigo_autorizacion: codAutRaw,
      has_safe_keys: hasSafeKeys,
    },
    binary: item.binary,
  },
];

const item = $input.first();

const isValid = !!item.json.validation?.is_valid;
const isDuplicateFile = !!item.json.duplicate?.is_duplicate_file;
const isDuplicateInvoice = !!item.json.duplicate?.is_duplicate_invoice;
const hasSafeKeys = !!item.json.has_safe_keys;
const hasInvoiceUid = !!item.json.invoice_uid;

const should_write_invoice =
  isValid &&
  hasSafeKeys &&
  hasInvoiceUid &&
  !isDuplicateFile &&
  !isDuplicateInvoice;

let duplicate_reason = '';
if (isDuplicateFile) {
  duplicate_reason = 'archivo_duplicado';
} else if (isDuplicateInvoice) {
  duplicate_reason = 'factura_duplicada';
}

let processing_status = 'pendiente';
let message = '';

if (!isValid) {
  processing_status = 'invalido';
  message = item.json.validation?.validation_message || 'Factura inválida';
} else if (!hasSafeKeys || !hasInvoiceUid) {
  processing_status = 'invalido';
  message = 'Factura inválida: faltan claves seguras para registrar';
} else if (isDuplicateFile || isDuplicateInvoice) {
  processing_status = 'duplicado';
  message = isDuplicateFile
    ? 'Archivo ya registrado'
    : 'Factura ya registrada';
} else {
  processing_status = 'procesado_ok';
  message = 'Factura procesada correctamente';
}

const duplicate_flag = isDuplicateFile || isDuplicateInvoice;

return [
  {
    json: {
      ...item.json,
      should_write_invoice,
      duplicate_flag,
      duplicate_reason,
      processing_status,
      message,
    },
    binary: item.binary,
  },
];

const source = $('Code - Write Decision').first();

const parsedInvoice = source.json.parsed_invoice || {};
const items = parsedInvoice.items || [];

function toNumber(value) {
  const num = Number(String(value ?? '').replace(/,/g, '').trim());
  return Number.isFinite(num) ? num : 0;
}

function round2(value) {
  return Math.round((Number(value) + Number.EPSILON) * 100) / 100;
}

const subtotalFactura = toNumber(parsedInvoice.subtotal);
const descuentoFacturaTotal = toNumber(parsedInvoice.descuento);

const baseProrrateo =
  subtotalFactura > 0
    ? subtotalFactura
    : items.reduce((acc, it) => acc + toNumber(it.subtotal), 0);

let descuentosProrrateados = [];

if (Array.isArray(items) && items.length > 0 && baseProrrateo > 0 && descuentoFacturaTotal > 0) {
  descuentosProrrateados = items.map((it) => {
    const subtotalItem = toNumber(it.subtotal);
    return round2((subtotalItem / baseProrrateo) * descuentoFacturaTotal);
  });

  // Ajuste en el último ítem para que la suma cierre exacta
  const sumaProrrateada = round2(
    descuentosProrrateados.reduce((acc, value) => acc + toNumber(value), 0)
  );

  const diferencia = round2(descuentoFacturaTotal - sumaProrrateada);

  descuentosProrrateados[descuentosProrrateados.length - 1] = round2(
    descuentosProrrateados[descuentosProrrateados.length - 1] + diferencia
  );
} else {
  descuentosProrrateados = items.map(() => 0);
}

const metodo_pago =
  source.json.metodo_pago ||
  parsedInvoice.metodo_pago ||
  'Efectivo';

const estado_ingreso =
  source.json.estado_ingreso ||
  parsedInvoice.estado_ingreso ||
  'Ya ingresado';

const fecha_estimada_ingreso =
  source.json.fecha_estimada_ingreso ||
  parsedInvoice.fecha_estimada_ingreso ||
  '';

const fecha_ingreso_real =
  source.json.fecha_ingreso_real ||
  parsedInvoice.fecha_ingreso_real ||
  '';

const nivel =
  source.json.nivel ||
  parsedInvoice.nivel ||
  'Venta en tienda';

if (!Array.isArray(items) || items.length === 0) {
  return [
    {
      json: {
        invoice_uid: source.json.invoice_uid || '',
        nro_factura: parsedInvoice.nro_factura || '',
        fecha_emision: parsedInvoice.fecha_emision || '',
        emisor_nit: parsedInvoice.emisor_nit || '',
        cliente_nombre: parsedInvoice.cliente_nombre || '',
        cliente_nit_ci: parsedInvoice.cliente_nit_ci || '',
        item_nro: '',
        codigo_producto: '',
        descripcion: '',
        cantidad: '',
        unidad_medida: '',
        tipo_producto: '',
        precio_unitario: '',
        descuento_item: '',
        subtotal_item: '',
        filename_original: source.json.filename_original || '',
        uploaded_at: source.json.uploaded_at || '',
        fecha_iso: parsedInvoice.fecha_iso || '',
        hora_24: parsedInvoice.hora_24 || '',
        datetime_iso: parsedInvoice.datetime_iso || '',
        anio: parsedInvoice.anio || '',
        mes: parsedInvoice.mes || '',
        trimestre: parsedInvoice.trimestre || '',
        dia_semana_nombre: parsedInvoice.dia_semana_nombre || '',
        franja_horaria: parsedInvoice.franja_horaria || '',
        mes_comercial: parsedInvoice.mes_comercial || '',
        semana_comercial_num: parsedInvoice.semana_comercial_num || '',
        semana_comercial: parsedInvoice.semana_comercial || '',
        orden_semana_comercial: parsedInvoice.orden_semana_comercial || '',
        ciudad: parsedInvoice.ciudad || '',
        sucursal: parsedInvoice.sucursal || '',
        punto_venta: parsedInvoice.punto_venta || '',
        codigo_tienda: parsedInvoice.codigo_tienda || '',
        nombre_tienda: parsedInvoice.nombre_tienda || '',
        uploaded_by: source.json.uploaded_by || '',
        uploaded_by_name: source.json.uploaded_by_name || source.json.uploaded_by || '',
        metodo_pago,
        estado_ingreso,
        fecha_estimada_ingreso,
        fecha_ingreso_real,
        nivel,
        _no_items: true,
      },
      binary: source.binary,
    }
  ];
}

return items.map((it, index) => {
  return {
    json: {
      invoice_uid: source.json.invoice_uid || '',
      nro_factura: parsedInvoice.nro_factura || '',
      fecha_emision: parsedInvoice.fecha_emision || '',
      emisor_nit: parsedInvoice.emisor_nit || '',
      cliente_nombre: parsedInvoice.cliente_nombre || '',
      cliente_nit_ci: parsedInvoice.cliente_nit_ci || '',
      item_nro: index + 1,
      codigo_producto: it.codigo || '',
      descripcion: it.descripcion || '',
      cantidad: it.cantidad ?? '',
      unidad_medida: it.unidad || '',
      tipo_producto: it.tipo_producto || '',
      precio_unitario: it.precio_unitario ?? '',
      descuento_item: it.descuento ?? '',
      subtotal_item: it.subtotal ?? '',
      descuento_factura_prorrateado: descuentosProrrateados[index] ?? 0,
      filename_original: source.json.filename_original || '',
      uploaded_at: source.json.uploaded_at || '',
      fecha_iso: parsedInvoice.fecha_iso || '',
      hora_24: parsedInvoice.hora_24 || '',
      datetime_iso: parsedInvoice.datetime_iso || '',
      anio: parsedInvoice.anio || '',
      mes: parsedInvoice.mes || '',
      trimestre: parsedInvoice.trimestre || '',
      dia_semana_nombre: parsedInvoice.dia_semana_nombre || '',
      franja_horaria: parsedInvoice.franja_horaria || '',
      mes_comercial: parsedInvoice.mes_comercial || '',
      semana_comercial_num: parsedInvoice.semana_comercial_num || '',
      semana_comercial: parsedInvoice.semana_comercial || '',
      orden_semana_comercial: parsedInvoice.orden_semana_comercial || '',
      ciudad: parsedInvoice.ciudad || '',
      sucursal: parsedInvoice.sucursal || '',
      punto_venta: parsedInvoice.punto_venta || '',
      codigo_tienda: parsedInvoice.codigo_tienda || '',
      nombre_tienda: parsedInvoice.nombre_tienda || '',
      uploaded_by: source.json.uploaded_by || '',
      uploaded_by_name: source.json.uploaded_by_name || source.json.uploaded_by || '',
      metodo_pago,
      estado_ingreso,
      fecha_estimada_ingreso,
      fecha_ingreso_real,
      nivel,
    },
    binary: source.binary,
  };
});

const source = $('Code - Write Decision').first();

return [
  {
    json: {
      ...source.json,
    },
    binary: source.binary,
  }
];

const item = $input.first();

// Después del merge, si Get row(s) in sheet encontró una fila previa en Procesamiento,
// normalmente vendrán campos reales de esa fila como process_id, status o message.
// No debemos usar file_hash del item actual para decidir duplicado.

const foundProcessId = item.json.process_id || null;
const foundStatus = item.json.status || null;
const foundMessage = item.json.message || null;

// Solo consideramos duplicado si vino una fila previa real desde la hoja
const isDuplicateFile = !!(foundProcessId && (foundStatus || foundMessage));

const duplicate = {
  ...(item.json.duplicate || {}),
  is_duplicate_file: isDuplicateFile,
  duplicate_type: isDuplicateFile ? 'duplicate_file' : null,
  duplicate_reason: isDuplicateFile ? 'file_hash' : null,
};

return [
  {
    json: {
      ...item.json,
      duplicate,
    },
    binary: item.binary,
  },
];

const item = $input.first();
const raw = item.json.text || '';

function norm(value) {
  return String(value || '')
    .replace(/\\n/g, '\n')
    .replace(/\r/g, '')
    .replace(/[ \t]+/g, ' ')
    .trim();
}

const text = norm(raw);

let invoice_format = 'UNKNOWN';
let confidence = 0;
let reasons = [];

// --- Señales específicas de A y B (van primero por ser más estrictas) ---
const hasTipoB =
  /Lugar y Fecha:/i.test(text) &&
  /Hora:/i.test(text) &&
  /C[ÓO]DIGO\s+CANTIDAD/i.test(text);

const hasTipoA =
  /Fecha:\s*\d{2}\/\d{2}\/\d{4}/i.test(text) &&
  /C[ÓO]DIGO\s+PRODUCTO\s*\/\s*SERVICIO/i.test(text);

// --- Formato C = rollo/ticket SENATEX ---
// NO depende de guiones (-----) porque el PDF no los exporta como texto.
const hasTipoC =
  /DETALLE/i.test(text) &&
  /MONTO A PAGAR/i.test(text) &&
  /(SUBTOTAL\s*Bs|IMPORTE BASE CR[ÉE]DITO FISCAL)/i.test(text) &&
  !/C[ÓO]DIGO\s+PRODUCTO\s*\/\s*SERVICIO/i.test(text) &&
  !(/Lugar y Fecha:/i.test(text) && /Hora:/i.test(text));

// Si además aparecen separadores de guiones, sube la confianza
const hasDashes = /-{5,}/.test(text);

if (hasTipoA) {
  invoice_format = 'A';
  confidence = 0.90;
  reasons.push('Formato clásico con Fecha y tabla CÓDIGO PRODUCTO / SERVICIO');
} else if (hasTipoB) {
  invoice_format = 'B';
  confidence = 0.90;
  reasons.push('Formato con Lugar y Fecha + Hora + tabla compacta');
} else if (hasTipoC) {
  invoice_format = 'C';
  confidence = hasDashes ? 0.95 : 0.85;
  reasons.push('Formato rollo/ticket con sección DETALLE y MONTO A PAGAR');
  if (!hasDashes) {
    reasons.push('Sin separadores de guiones en el texto extraído (normal en PDFs SENATEX)');
  }
} else {
  confidence = 0.30;
  reasons.push('No se pudo identificar claramente el formato');
}

return [
  {
    json: {
      ...item.json,
      invoice_format,
      invoice_format_confidence: confidence,
      invoice_format_reasons: reasons,
    },
    binary: item.binary,
  },
];

//Tipo A
const item = $input.first();
const text = item.json.text || '';
const webhookBody = $('Webhook').first().json.body || {};
const binary = item.binary || {};

function cleanText(value) {
  return (value || '')
    .replace(/\\n/g, '\n')
    .replace(/\r/g, '')
    .replace(/[ \t]+/g, ' ')
    .trim();
}

const raw = cleanText(text);

const emisor_razon_social = /SENATEX/i.test(raw)
  ? 'SERVICIO NACIONAL TEXTIL - SENATEX'
  : (() => {
      const lineas = raw
        .split('\n')
        .map(l => l.trim())
        .filter(Boolean);

      const candidatas = lineas.slice(0, 8).filter(l =>
        !/^NIT[:\b]/i.test(l) &&
        !/^FACTURA\b/i.test(l) &&
        !/^N[°ºo]?\s*FACTURA\b/i.test(l) &&
        !/^SUCURSAL\b/i.test(l) &&
        !/^No\.\s*Punto de Venta\b/i.test(l) &&
        !/^-\s*PUNTO DE VENTA\b/i.test(l) &&
        !/^PUNTO DE VENTA\b/i.test(l) &&
        !/^Lugar y Fecha:/i.test(l) &&
        !/^Hora:/i.test(l)
      );

      if (!candidatas.length) return null;

      return candidatas
        .slice(0, 2)
        .join(' ')
        .replace(/\s+/g, ' ')
        .trim();
    })();

const flat = raw.replace(/\n+/g, ' ').replace(/\s+/g, ' ').trim();
// Cantidades: puede ser 1, 1.00, 2.5, etc.
const NUM_PATTERN = '[0-9][0-9.,]*(?:[.,][0-9]{1,4})?';

// Montos: precio, descuento y subtotal.
// IMPORTANTE: exige 2 decimales para no confundir tallas/modelos como "9", "12", "XL", etc.
const MONEY_PATTERN = '[0-9][0-9.,]*(?:[.,][0-9]{2})';

function extract(pattern, source, group = 1) {
  const match = source.match(pattern);
  return match ? (match[group] || '').trim() : null;
}

function extractAmountByLabels(labels, source) {
  for (const label of labels) {
    const escaped = label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const regex = new RegExp(
      `(?:^|\\n)\\s*${escaped}\\s+Bs\\.?\\s*([0-9][0-9,]*(?:\\.[0-9]{2})?)`,
      'im'
    );
    const match = source.match(regex);
    if (match) return parseAmount(match[1]);
  }
  return null;
}

function normalizeSpaces(value) {
  return (value || '').replace(/\s+/g, ' ').trim();
}

const UNIT_PATTERN =
  'Piezas|Pieza|Pies|Pie|Unidad\\s*\\(Bienes\\)|Unidad\\s*\\(Servicios\\)|Unidad|Unidades|Docena|Docenas|Metro|Metros|Kilogramo|Kilogramos|Kg|Kgs|Juego|Juegos';

function normalizeUnitRaw(value) {
  return (value || '')
    .toUpperCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function mapUnidadNorm(rawUnit) {
  const value = normalizeUnitRaw(rawUnit)
    .replace(/\s*\(\s*/g, ' (')
    .replace(/\s*\)\s*/g, ')')
    .replace(/\s+/g, ' ')
    .trim();

  if (!value) return 'OTRO';

  if (['KILOGRAMO', 'KILOGRAMOS', 'KG', 'KGS'].includes(value)) return 'KG';
  if (['PIEZA', 'PIEZAS', 'PIE', 'PIES'].includes(value)) return 'PZA';
  if (['JUEGO', 'JUEGOS'].includes(value)) return 'JGO';
  if (['METRO', 'METROS'].includes(value)) return 'MTR';
  if (['DOCENA', 'DOCENAS'].includes(value)) return 'DOC';
  if (['UNIDAD (SERVICIOS)'].includes(value)) return 'SERV_UND';
  if (['UNIDAD', 'UNIDADES', 'UNIDAD (BIENES)'].includes(value)) return 'UND';

  return 'OTRO';
}

function deriveTipoProducto(unidadNorm) {
  if (unidadNorm === 'KG') return 'TELA';
  if (unidadNorm === 'SERV_UND') return 'SERVICIO';
  if (['PZA', 'JGO', 'UND', 'MTR', 'DOC'].includes(unidadNorm)) return 'PRODUCTO';
  return 'POR_CLASIFICAR';
}

function parseAmount(value) {
  if (value == null) return null;

  let s = String(value)
    .replace(/\s+/g, '')
    .trim();

  if (!s) return null;

  const lastComma = s.lastIndexOf(',');
  const lastDot = s.lastIndexOf('.');

  if (lastComma !== -1 && lastDot !== -1) {
    if (lastComma > lastDot) {
      // Formato 1.234,56
      s = s.replace(/\./g, '').replace(',', '.');
    } else {
      // Formato 1,234.56
      s = s.replace(/,/g, '');
    }
  } else if (lastComma !== -1) {
    // Formato 1234,56
    s = s.replace(',', '.');
  }

  const num = Number(s);
  return Number.isFinite(num) ? num : null;
}

function parseFechaISO(fechaStr) {
  if (!fechaStr) return null;
  const match = fechaStr.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if (!match) return null;

  const [, dd, mm, yyyy] = match;
  return `${yyyy}-${mm}-${dd}`;
}

function parseHora24(horaStr) {
  if (!horaStr) return null;

  const clean = horaStr.trim();

  // Caso 24h: 13:14:24 o 13:14
  let match24 = clean.match(/^(\d{1,2}):(\d{2})(?::(\d{2}))?$/);
  if (match24) {
    const hh = String(Number(match24[1])).padStart(2, '0');
    const mm = match24[2];
    const ss = match24[3] || '00';
    return `${hh}:${mm}:${ss}`;
  }

  const normalized = clean
    .toLowerCase()
    .replace(/\s+/g, '')
    .replace('a.m.', 'am')
    .replace('p.m.', 'pm')
    .replace('a.m', 'am')
    .replace('p.m', 'pm');

  const match = normalized.match(/^(\d{1,2}):(\d{2})(am|pm)$/);
  if (!match) return null;

  let [, hh, mm, period] = match;
  let hour = Number(hh);

  if (period === 'pm' && hour !== 12) hour += 12;
  if (period === 'am' && hour === 12) hour = 0;

  return `${String(hour).padStart(2, '0')}:${mm}:00`;
}

function pad2(n) {
  return String(n).padStart(2, '0');
}

function parseISODateLocal(fechaISO) {
  if (!fechaISO) return null;

  const match = String(fechaISO).match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) return null;

  const [, yyyy, mm, dd] = match;
  return new Date(Number(yyyy), Number(mm) - 1, Number(dd));
}

function formatShortDateEs(date) {
  const meses = [
    'ene', 'feb', 'mar', 'abr', 'may', 'jun',
    'jul', 'ago', 'sep', 'oct', 'nov', 'dic'
  ];

  return `${pad2(date.getDate())} ${meses[date.getMonth()]}`;
}

function monthNameEs(monthNumber) {
  return [
    'Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio',
    'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'
  ][monthNumber - 1];
}

function startOfCommercialWeek(date) {
  const d = new Date(date);
  const day = d.getDay(); // 0 domingo, 1 lunes, ..., 6 sábado

  // Si es domingo, vuelve al lunes anterior.
  // Pero igual el domingo quedará fuera de semana comercial.
  const diff = day === 0 ? -6 : 1 - day;

  d.setDate(d.getDate() + diff);
  d.setHours(0, 0, 0, 0);

  return d;
}

function addDays(date, days) {
  const d = new Date(date);
  d.setDate(d.getDate() + days);
  return d;
}

function getCommercialWeekParts(fechaISO) {
  const empty = {
    mes_comercial: '',
    semana_comercial_num: '',
    semana_comercial: '',
    orden_semana_comercial: '',
  };

  const dt = parseISODateLocal(fechaISO);
  if (!dt) return empty;

  const diaSemana = dt.getDay(); // 0 domingo

  // SENATEX: semana comercial solo de lunes a sábado.
  // Domingo queda fuera del filtro semanal.
  if (diaSemana === 0) return empty;

  const inicioSemana = startOfCommercialWeek(dt);
  const finSemana = addDays(inicioSemana, 5); // sábado

  // El jueves define a qué mes pertenece la semana.
  // Ejemplo: 29 jun - 04 jul pertenece a Julio 2026.
  const juevesControl = addDays(inicioSemana, 3);

  const anioComercial = juevesControl.getFullYear();
  const mesComercialNum = juevesControl.getMonth() + 1;
  const mesComercialNombre = monthNameEs(mesComercialNum);

  const primerDiaMes = new Date(anioComercial, mesComercialNum - 1, 1);
  const primerJueves = new Date(primerDiaMes);

  while (primerJueves.getDay() !== 4) {
    primerJueves.setDate(primerJueves.getDate() + 1);
  }

  const inicioPrimeraSemana = startOfCommercialWeek(primerJueves);

  const diferenciaDias = Math.round((inicioSemana - inicioPrimeraSemana) / 86400000);
  const semanaNum = Math.floor(diferenciaDias / 7) + 1;

  const rango = `${formatShortDateEs(inicioSemana)} al ${formatShortDateEs(finSemana)}`;

  return {
    mes_comercial: `${mesComercialNombre} ${anioComercial}`,
    semana_comercial_num: semanaNum,
    semana_comercial: `Semana ${semanaNum} | ${rango}`,
    orden_semana_comercial: Number(`${anioComercial}${pad2(mesComercialNum)}${pad2(semanaNum)}`),
  };
}

function getDateParts(fechaISO, hora24) {
  if (!fechaISO) {
    return {
      fecha_iso: null,
      hora_24: hora24 || null,
      datetime_iso: null,
      anio: null,
      mes: null,
      dia: null,
      trimestre: null,
      semana_anio: null,
      dia_semana_num: null,
      dia_semana_nombre: null,
      franja_horaria: null,
      ...getCommercialWeekParts(null),
    };
  }

  const dt = new Date(`${fechaISO}T${hora24 || '00:00:00'}`);

  const anio = dt.getFullYear();
  const mes = dt.getMonth() + 1;
  const dia = dt.getDate();
  const trimestre = Math.ceil(mes / 3);
  const dia_semana_num = dt.getDay(); // 0=domingo
  const dia_semana_nombre = ['Domingo', 'Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado'][dia_semana_num];

  const hour = dt.getHours();
  let franja_horaria = null;
  if (hour >= 0 && hour < 6) franja_horaria = 'Madrugada';
  else if (hour < 12) franja_horaria = 'Mañana';
  else if (hour < 18) franja_horaria = 'Tarde';
  else franja_horaria = 'Noche';

  const commercialWeekParts = getCommercialWeekParts(fechaISO);

  const inicioAnio = new Date(dt.getFullYear(), 0, 1);
  const dias = Math.floor((dt - inicioAnio) / 86400000);
  const semana_anio = Math.ceil((dias + inicioAnio.getDay() + 1) / 7);

  return {
    fecha_iso: fechaISO,
    hora_24: hora24 || null,
    datetime_iso: hora24 ? `${fechaISO}T${hora24}` : `${fechaISO}T00:00:00`,
    anio,
    mes,
    dia,
    trimestre,
    semana_anio,
    dia_semana_num,
    dia_semana_nombre,
    franja_horaria,
    ...commercialWeekParts,
  };
}

function parseFechaTextoISO(fechaStr) {
  if (!fechaStr) return null;

  const meses = {
    enero: '01',
    febrero: '02',
    marzo: '03',
    abril: '04',
    mayo: '05',
    junio: '06',
    julio: '07',
    agosto: '08',
    septiembre: '09',
    setiembre: '09',
    octubre: '10',
    noviembre: '11',
    diciembre: '12',
  };

  const clean = normalizeSpaces(fechaStr)
    .toLowerCase()
    .replace(/\s*,\s*/g, ' ')
    .trim();

  const match = clean.match(/(\d{1,2})\s+de\s+([a-záéíóú]+)\s+de\s+(\d{4})/i);
  if (!match) return null;

  const dd = String(Number(match[1])).padStart(2, '0');
  const mesTxt = match[2]
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
  const yyyy = match[3];
  const mm = meses[mesTxt];

  if (!mm) return null;

  return `${yyyy}-${mm}-${dd}`;
}

// Hash simple y determinístico del archivo (sin depender de módulos externos)
function simpleHash(str) {
  let hash = 2166136261; // FNV-1a base
  for (let i = 0; i < str.length; i++) {
    hash ^= str.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

