function extractItemsBlock(source) {
  const startMatch =
    source.match(/C[ÓO]DIGO\s+PRODUCTO\s*\/\s*SERVICIO/i) ||
    source.match(/C[ÓO]DIGO\s+CANTIDAD/i);

