  const startIndex = startMatch.index;
  const tail = source.slice(startIndex);

  const endMatch =
    tail.match(/SUBTOTAL\s+Bs\.?/i) ||
    tail.match(/SON:/i);

  if (!endMatch) return tail;

  return tail.slice(0, endMatch.index);
}

function isCodeLike(line) {
  const value = normalizeSpaces(line || '');
  return /^[A-Z0-9\/.\-',]+$/i.test(value) && /[A-Z]/i.test(value);
}

function isCodeLikeWithSpaces(line) {
  const value = normalizeSpaces(line);
  if (!value) return false;

  if (isHeaderNoiseLine(value)) return false;

  // Permitir letras acentuadas y Ñ/Ü
  if (!/^[A-Z0-9ÁÉÍÓÚÑÜ\/.\-',\s]+$/i.test(value)) return false;

  const tokens = value.split(/\s+/);

  if (tokens.length < 2 || tokens.length > 6) return false;

  const hasLetter = tokens.some(t => /[A-ZÁÉÍÓÚÑÜ]/i.test(t));
  const hasCodeSignal = tokens.some(t => /[0-9\/.\-']/.test(t));

  return hasLetter && hasCodeSignal;
}

function isMergeableCodeFragment(line) {
  const value = normalizeSpaces(line);
  if (!value) return false;

  if (isHeaderNoiseLine(value)) return false;
  if (!/^[A-Z0-9ÁÉÍÓÚÑÜ\/.\-',\s]+$/i.test(value)) return false;

  if (
    parseQtyUnitLine(value) ||
    parseAmountOnlyLine(value) !== null ||
    parseUnitOnlyLine(value) ||
    parseAmountTripleLine(value) ||
    parseDescriptionAndTripleLine(value) ||
    parseFullInlineItem(value) ||
    parseSimpleInlineItem(value) ||
    parseCodeQtyUnitDescriptionLine(value) ||
    parseCodeQtyUnitDescriptionAndTripleLine(value) ||
    parseCodeFragmentQtyUnitLine(value) ||
    parseCodeWithSpacesQtyUnitLine(value) ||
    parseCodeTextQtyUnitLine(value)
  ) {
    return false;
  }

  const tokens = value.split(/\s+/);

  // Permitimos hasta 3 tokens para casos como:
  // ETBH005.AZUL
  // TAQUIÑA.M
  // o TOPO GRIS CL.XL
  if (tokens.length > 3) return false;

  // Si son solo palabras puras sin puntos ni números, no fusionar
  const hasDigit = /[0-9]/.test(value);
  const hasDotSlashHyphen = /[./\-']/.test(value);
  const hasLetter = /[A-ZÁÉÍÓÚÑÜ]/i.test(value);

  if (!hasLetter) return false;
  if (!hasDigit && !hasDotSlashHyphen) return false;

  return true;
}

function hasCodeSignal(line) {
  return /[0-9\/.\-']/.test(normalizeSpaces(line || ''));
}

function isUpperTextFragment(line) {
  const value = normalizeSpaces(line);
  if (!value) return false;
  if (isHeaderNoiseLine(value)) return false;

  // Permitir Ñ y vocales acentuadas
  if (!/^[A-ZÁÉÍÓÚÑÜ.\-\/'\s]+$/i.test(value)) return false;

  const tokens = value.split(/\s+/);

  if (tokens.length < 1 || tokens.length > 5) return false;

  return /[A-ZÁÉÍÓÚÑÜ]/i.test(value);
}

function isNumericCodeSuffix(line) {
  const value = normalizeSpaces(line || '');

  return (
    /^[0-9]{1,3}$/.test(value) ||     // 4, 12, 123
    /^\.[0-9]{1,3}$/.test(value) ||   // .12, .6
    /^\.[A-Z0-9]{1,4}$/i.test(value)  // .XS, .M, .12
  );
}

function isCodeContinuationFragment(line) {
  const value = normalizeSpaces(line || '');
  if (!value) return false;

  // Permitir fragmentos tipo:
  // SCURO.S
  // NRY.L
  // .12
  // .XS
  // AZUL.M
  if (!/^[A-Z0-9\/.\-',]+$/i.test(value)) return false;

  // No debe ser una unidad, cantidad o línea de montos completas
  if (
    parseQtyUnitLine(value) ||
    parseAmountOnlyLine(value) !== null ||
    parseUnitOnlyLine(value) ||
    parseAmountTripleLine(value)
  ) {
    return false;
  }

  // Aceptar específicamente fragmentos que empiezan con punto
  if (/^\.[A-Z0-9]{1,4}$/i.test(value)) {
    return true;
  }

  return true;
}

function joinCodeParts(left, right) {
  const a = normalizeSpaces(left || '');
  const b = normalizeSpaces(right || '');

  if (!a) return b;
  if (!b) return a;

  // Si el primer fragmento termina con punto, slash, guion o apóstrofe, unir sin espacio
  if (/[.,/\-']$/.test(a)) {
    return `${a}${b}`;
  }

  // Si el segundo fragmento parece continuación técnica del código, unir sin espacio
  if (isCodeContinuationFragment(b)) {
    return `${a}${b}`;
  }

  // En otros casos, unir con espacio
  return `${a} ${b}`;
}

function extractLeadingCode(value) {
  const text = normalizeSpaces(value || '');
  if (!text) return text;

  const firstToken = text.split(/\s+/)[0] || '';

  // Si el primer token parece un código real, usarlo
  if (/^[A-Z0-9][A-Z0-9\/.\-',]*$/i.test(firstToken) && /[0-9]/.test(firstToken)) {
    return firstToken;
  }

  return text;
}



function isSuspiciousCode(code) {
  const value = normalizeSpaces(code || '').toUpperCase();
  if (!value) return true;

  // Si tiene espacios, casi seguro no es un código puro
  if (/\s/.test(value)) return true;

  // Debe tener al menos una letra o número
  if (!/[A-Z0-9]/.test(value)) return true;

  // Casos válidos cortos de SENATEX:
  // P72, P71, P5, P16, BAV001, ETBOA05, CHRM006, RP11090A, etc.
  if (/^[A-Z]{1,4}[0-9]{1,6}[A-Z0-9\-./']*$/i.test(value)) return false;

  // Códigos con mezcla normal de letras/números
  if (/^[A-Z0-9][A-Z0-9\-./']{2,}$/i.test(value) && /[0-9]/.test(value)) return false;

  // Si no tiene dígitos, normalmente no es código
  if (!/[0-9]/.test(value)) return true;

  return false;
}

function shouldPromoteDescriptionAsCode(codigo, descripcion) {
  const cod = normalizeSpaces(codigo || '');
  const desc = normalizeSpaces(descripcion || '');

  if (!cod || !desc) return false;

  // Solo promover si el código original realmente parece inválido
  if (!isSuspiciousCode(cod)) return false;

  // Nunca promover descripciones con espacios
  if (/\s/.test(desc)) return false;

  // Solo promover si la "descripción" parece realmente un código
  if (/^[A-Z]{1,4}[0-9]{1,6}[A-Z0-9\-./']*$/i.test(desc)) return true;
  if (/^[A-Z0-9][A-Z0-9\-./']{3,}$/i.test(desc) && /[0-9]/.test(desc)) return true;

  return false;
}

function parseQtyUnitLine(line) {
  const match = (line || '').match(
    new RegExp(`^(${NUM_PATTERN})\\s+(${UNIT_PATTERN})$`, 'i')
  );
  if (!match) return null;

  return {
    cantidad: parseAmount(match[1]),
    unidad: normalizeSpaces(match[2]),
  };
}

function findQtyUnitAhead(lines, startIndex, maxLookahead = 3) {
  for (let offset = 1; offset <= maxLookahead; offset++) {
    const candidate = lines[startIndex + offset];
    const parsed = parseQtyUnitLine(candidate);

    if (parsed) {
      return {
        index: startIndex + offset,
        cantidad: parsed.cantidad,
        unidad: parsed.unidad,
      };
    }
  }

  return null;
}

function parseAmountOnlyLine(line) {
  const match = (line || '').match(new RegExp(`^(${NUM_PATTERN})$`));
  return match ? parseAmount(match[1]) : null;
}

function parseMoneyOnlyLine(line) {
  const match = (line || '').match(new RegExp(`^(${MONEY_PATTERN})$`));
  return match ? parseAmount(match[1]) : null;
}

function round2(value) {
  const n = Number(value || 0);
  return Number.isFinite(n) ? Math.round(n * 100) / 100 : 0;
}

function parseUnitOnlyLine(line) {
  const match = (line || '').match(new RegExp(`^(${UNIT_PATTERN})$`, 'i'));
  return match ? normalizeSpaces(match[1]) : null;
}

function parseParentesisUnidadLine(line) {
  const value = normalizeSpaces(line || '');

  if (/^\(?Bienes\)?$/i.test(value)) return 'Unidad (Bienes)';
  if (/^\(?Servicios\)?$/i.test(value)) return 'Unidad (Servicios)';

  return null;
}

function parseAmountTripleLine(line) {
  const match = (line || '').match(
    new RegExp(`^(${MONEY_PATTERN})\\s+(${MONEY_PATTERN})\\s+(${MONEY_PATTERN})$`, 'i')
  );

  if (!match) return null;

  return {
    precio_unitario: parseAmount(match[1]),
    descuento: parseAmount(match[2]),
    subtotal: parseAmount(match[3]),
  };
}

function parseAmountQuadLine(line) {
  const match = (line || '').match(
    new RegExp(`^(${MONEY_PATTERN})\\s+(${MONEY_PATTERN})\\s+(${MONEY_PATTERN})\\s+(${MONEY_PATTERN})$`, 'i')
  );

  if (!match) return null;

  return {
    precio_base: parseAmount(match[1]),
    precio_unitario: parseAmount(match[2]),
    descuento: parseAmount(match[3]),
    subtotal: parseAmount(match[4]),
  };
}

function parseDescriptionAndTripleLine(line) {
  const quad = parseAmountQuadLine(line);
  if (quad) {
    return {
      descripcion_extra: '',
      precio_unitario: quad.precio_unitario,
      descuento: quad.descuento,
      subtotal: quad.subtotal,
    };
  }

  const match = (line || '').match(
    new RegExp(`^(.*?)\\s+(${MONEY_PATTERN})\\s+(${MONEY_PATTERN})\\s+(${MONEY_PATTERN})$`, 'i')
  );

  if (!match) return null;

  return {
    descripcion_extra: normalizeSpaces(match[1]),
    precio_unitario: parseAmount(match[2]),
    descuento: parseAmount(match[3]),
    subtotal: parseAmount(match[4]),
  };
}

function parseDescriptionAndBrokenTripleLines(line1, line2) {
  const a = normalizeSpaces(line1 || '');
  const b = normalizeSpaces(line2 || '');

  if (!a || !b) return null;

  const match = a.match(
    new RegExp(`^(.*?)\\s+(${MONEY_PATTERN})\\s+(${MONEY_PATTERN})$`, 'i')
  );

  if (!match) return null;

  const subtotal = parseMoneyOnlyLine(b);
  if (subtotal === null) return null;

  return {
    descripcion_extra: normalizeSpaces(match[1]),
    precio_unitario: parseAmount(match[2]),
    descuento: parseAmount(match[3]),
    subtotal,
  };
}

function parseFullInlineItem(line) {
  const match = (line || '').match(
    new RegExp(
      `^([A-Z0-9\\/\\.\\-',]+)\\s+(.*?)\\s+(${NUM_PATTERN})\\s+(${UNIT_PATTERN})\\s+(.*?)\\s+(${MONEY_PATTERN})\\s+(${MONEY_PATTERN})\\s+(${MONEY_PATTERN})$`,
      'i'
    )
  );

  if (!match) return null;

  return {
    codigo: normalizeSpaces(match[1]).replace(/\s+/g, ''),
    cantidad: parseAmount(match[3]),
    unidad: normalizeSpaces(match[4]),
    descripcion: normalizeSpaces(match[5]),
    precio_unitario: parseAmount(match[6]),
    descuento: parseAmount(match[7]),
    subtotal: parseAmount(match[8]),
  };
}

function parseSimpleInlineItem(line) {
  const match = (line || '').match(
