  if (!match) return null;

  return {
    codigo: normalizeSpaces(match[1]).replace(/\s+/g, ''),
    cantidad: parseAmount(match[2]),
    unidad: normalizeSpaces(match[3]),
    descripcion: normalizeSpaces(match[4]),
    precio_unitario: parseAmount(match[5]),
    descuento: parseAmount(match[6]),
