      `^(.*?)\\s+(${NUM_PATTERN})\\s+(${UNIT_PATTERN})\\s+(.*?)\\s+(${MONEY_PATTERN})\\s+(${MONEY_PATTERN})\\s+(${MONEY_PATTERN})$`,
