  };
}

function parseQtyUnitDescriptionAndTripleLine(line) {
  const match = (line || '').match(
    new RegExp(
      `^(${NUM_PATTERN})\\s+(${UNIT_PATTERN})\\s+(.*?)\\s+(${MONEY_PATTERN})\\s+(${MONEY_PATTERN})\\s+(${MONEY_PATTERN})$`,
