    subtotal: parseAmount(match[6]),
  };
}

function parseCodeFragmentQtyUnitLine(line) {
  const match = (line || '').match(
    new RegExp(`^([A-Z0-9\\/\\.\\-',]+)\\s+(${NUM_PATTERN})\\s+(${UNIT_PATTERN})$`, 'i')
  );

  if (!match) return null;

  return {
    fragmento_codigo: normalizeSpaces(match[1]),
    cantidad: parseAmount(match[2]),
    unidad: normalizeSpaces(match[3]),
  };
}

function parseCodeWithSpacesQtyUnitLine(line) {
  const match = (line || '').match(
    new RegExp(`^(.*?)\\s+(${NUM_PATTERN})\\s+(${UNIT_PATTERN})$`, 'i')
  );

  if (!match) return null;

  const codigo = normalizeSpaces(match[1]);

  if (!isCodeLikeWithSpaces(codigo)) return null;

  return {
    codigo,
    cantidad: parseAmount(match[2]),
    unidad: normalizeSpaces(match[3]),
  };
}

function parseCodeTextQtyUnitLine(line) {
  const match = (line || '').match(
    new RegExp(`^(.*?)\\s+(${NUM_PATTERN})\\s+(${UNIT_PATTERN})$`, 'i')
  );

  if (!match) return null;

  const codigo = normalizeSpaces(match[1]);

  // aquí sí permitimos código con texto/color al final, incluyendo Ñ/acentos
  if (!codigo || !/[A-Z0-9ÁÉÍÓÚÑÜ]/i.test(codigo)) return null;

  return {
    codigo,
    cantidad: parseAmount(match[2]),
    unidad: normalizeSpaces(match[3]),
  };
}

function splitCombinedLines(lines) {
  const result = [];

  const unitPattern = `(?:${UNIT_PATTERN})`;
  const triplePattern = `${MONEY_PATTERN}\\s+${MONEY_PATTERN}\\s+${MONEY_PATTERN}`;

  for (const rawLine of lines) {
    let pending = [normalizeSpaces(rawLine)];

    while (pending.length) {
      const value = pending.shift();

      const match = value.match(
        new RegExp(`^(.*?${triplePattern})\\s+(.+)$`, 'i')
      );

      if (!match) {
        result.push(value);
        continue;
      }

      const left = normalizeSpaces(match[1]);
      const right = normalizeSpaces(match[2]);

      const rightLooksLikeNewItem =
        new RegExp(`^[A-Z0-9\\/\\.\\-'\\s]+\\s+${NUM_PATTERN}\\s+${unitPattern}(?:\\s+.+)?$`, 'i').test(right) ||
        new RegExp(`^[A-Z0-9\\/\\.\\-'\\s]+$`, 'i').test(right);

      if (rightLooksLikeNewItem) {
        pending.unshift(right);
        pending.unshift(left);
      } else {
        result.push(value);
      }
    }
  }

  return result;
}

function isHeaderNoiseLine(line) {
  const raw = normalizeSpaces(line).toUpperCase();
  const value = raw
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, '');

  if (!value) return false;

  return (
    value === 'CODIGO' ||
    value === 'PRODUCTO' ||
    value === '/' ||
    value === 'PRODUCTO/' ||
    value === 'SERVICIO' ||
    value === 'CANTIDAD' ||
    value === 'UNIDAD' ||
    value === 'DE' ||
    value === 'UNIDADDE' ||
    value === 'MEDIDA' ||
    value === 'UNIDADDEMEDIDA' ||
    value === 'DESCRIPCION' ||
    value === 'PRECIO' ||
    value === 'UNITARIO' ||
    value === 'PRECIOUNITARIO' ||
    value === 'DESCUENTO' ||
    value === 'SUBTOTAL' ||
    value === 'DESCUENTOSUBTOTAL' ||
    value === 'PRODUCTO/SERVICIO' ||
    value.startsWith('PRODUCTO/') ||
    value.startsWith('UNIDADDE') ||
    value.startsWith('UNIDADDEMED') ||
    value.startsWith('PRECIOUNIT') ||
    value.startsWith('DESCRIPC') ||
    value.startsWith('DESCUENTOSUBTOTAL')
  );
}


function cleanItemsLines(block) {
  if (!block) return [];

  const lines = block
    .split('\n')
    .map(l => normalizeSpaces(l))
    .filter(Boolean);

  const result = [];

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const prev = normalizeSpaces(lines[i - 1] || '');
    const next = normalizeSpaces(lines[i + 1] || '');
    // Saltar marcadores de página: 1/2, 2/2, etc.
    if (/^\d+\s*\/\s*\d+$/.test(line)) {
      continue;
    }

    if (/^Son:/i.test(line)) {
      break;
    }

    // Encabezado clásico
    if (/C[ÓO]DIGO\s+PRODUCTO/i.test(line)) {
      continue;
    }

    // Encabezado TCPDF
    if (/^C[ÓO]DIGO\s+CANTIDAD$/i.test(line)) {
      continue;
    }

    // Mantener UNIDAD si forma parte del dato real:
    // 1
    // UNIDAD
    // (BIENES)
    const isUnidadDato =
      /^UNIDAD$/i.test(line) &&
      /^\(?\s*(BIENES|SERVICIOS)\s*\)?$/i.test(next) &&
      (
        /^[0-9]+(?:\.[0-9]+)?$/.test(prev) ||
        /^[A-Z0-9\/.\-',]+\s+[0-9]+(?:\.[0-9]+)?$/i.test(prev)
      );

    if (isUnidadDato) {
      result.push(line);
      continue;
    }

    if (isHeaderNoiseLine(line)) {
      continue;
    }

    result.push(line);
  }

  return result;
}

function fixBrokenUnidadLines(lines) {
  const result = [];

  for (let i = 0; i < lines.length; i++) {
    const current = normalizeSpaces(lines[i]);
    const next = normalizeSpaces(lines[i + 1] || '');

    // Caso:
    // UNIDAD
    // (BIENES)
    if (
      /^UNIDAD$/i.test(current) &&
      /^\(?\s*(BIENES|SERVICIOS)\s*\)?$/i.test(next)
    ) {
      const tipo = next.replace(/[()]/g, '').trim();
      result.push(`Unidad (${tipo})`);
      i += 1;
      continue;
    }

    result.push(current);
  }

  return result;
}



function mergeBrokenCodeLines(lines) {
  const merged = [];

  for (let i = 0; i < lines.length; i++) {
    let current = normalizeSpaces(lines[i]);
    let j = i;

    if (isHeaderNoiseLine(current)) {
      continue;
    }

    if (!isMergeableCodeFragment(current)) {
      merged.push(current);
      continue;
    }

    while (j + 1 < lines.length) {
      const next = normalizeSpaces(lines[j + 1]);
      const next2 = normalizeSpaces(lines[j + 2] || '');

      if (!next || isHeaderNoiseLine(next)) {
        break;
      }

      // Caso 1: fragmento + fragmento mergeable
      if (isMergeableCodeFragment(next)) {
        current = joinCodeParts(current, next);
        j += 1;
        continue;
      }

      // Caso 2: sufijo numérico del código antes de cantidad/unidad
      if (
        hasCodeSignal(current) &&
        isNumericCodeSuffix(next) &&
        parseQtyUnitLine(next2)
      ) {
        current = joinCodeParts(current, next);
        j += 1;
        continue;
      }

      // Caso 3: texto/código en segunda línea y luego cantidad
      // Ejemplo:
      // ETBH005.AZUL
      // TAQUIÑA.M
      // 1.00 Piezas
      if (
        isMergeableCodeFragment(current) &&
        isMergeableCodeFragment(next) &&
        parseQtyUnitLine(next2)
      ) {
        current = joinCodeParts(current, next);
        j += 1;
        continue;
      }

      // Caso 4: código con señal + texto fragmentado + luego cantidad
      // Ejemplo:
      // CHRM001 ROJO
      // SALMON XS
      // 1.00 Piezas
      if (
        hasCodeSignal(current) &&
        (isUpperTextFragment(next) || isMergeableCodeFragment(next)) &&
        (parseQtyUnitLine(next2) || parseAmountOnlyLine(next2) !== null)
      ) {
        current = joinCodeParts(current, next);
        j += 1;
        continue;
      }

      break;
    }

    merged.push(normalizeSpaces(current));
    i = j;
  }

  return merged;
}

const itemsBlock = extractItemsBlock(raw);

let itemLines_clean = cleanItemsLines(itemsBlock);

// 👇 NUEVO PASO
let itemLines_fixed = fixBrokenUnidadLines(itemLines_clean);

let itemLines_merge1 = mergeBrokenCodeLines(itemLines_fixed);
let itemLines_split = splitCombinedLines(itemLines_merge1);
let itemLines = mergeBrokenCodeLines(itemLines_split);

const items = [];
let idx = 0;

while (idx < itemLines.length) {
  let codigo = null;
  let cantidad = null;
  let unidad = null;

  const line = itemLines[idx];
  const next = itemLines[idx + 1];
  const next2 = itemLines[idx + 2];

  const simpleInline = parseSimpleInlineItem(line);
  if (simpleInline) {
    const unidadNorm = mapUnidadNorm(simpleInline.unidad);

    items.push({
      codigo: simpleInline.codigo,
      cantidad: simpleInline.cantidad,
      unidad: unidadNorm,
      tipo_producto: deriveTipoProducto(unidadNorm),
      descripcion: simpleInline.descripcion,
      precio_unitario: simpleInline.precio_unitario,
      descuento: simpleInline.descuento,
      subtotal: simpleInline.subtotal,
    });
    idx += 1;
    continue;
  }

  const fullInline = parseFullInlineItem(line);
  if (fullInline) {
    const codigoFinal =
    shouldPromoteDescriptionAsCode(fullInline.codigo, fullInline.descripcion)
      ? fullInline.descripcion
      : fullInline.codigo;

    const unidadNorm = mapUnidadNorm(fullInline.unidad);

    items.push({
      codigo: codigoFinal,
      cantidad: fullInline.cantidad,
      unidad: unidadNorm,
      tipo_producto: deriveTipoProducto(unidadNorm),
      descripcion: fullInline.descripcion,
      precio_unitario: fullInline.precio_unitario,
      descuento: fullInline.descuento,
      subtotal: fullInline.subtotal,
    });
    idx += 1;
    continue;
  }

  const qtyUnitDescTripleNext = parseQtyUnitDescriptionAndTripleLine(next);

  if (
    (isCodeLike(line) || isCodeLikeWithSpaces(line)) &&
    qtyUnitDescTripleNext
  ) {
    const codigoFinal = normalizeSpaces(line).replace(/\s+/g, '');
    const unidadNorm = mapUnidadNorm(qtyUnitDescTripleNext.unidad);

    items.push({
      codigo: codigoFinal,
      cantidad: qtyUnitDescTripleNext.cantidad,
      unidad: unidadNorm,
      tipo_producto: deriveTipoProducto(unidadNorm),
      descripcion: qtyUnitDescTripleNext.descripcion,
      precio_unitario: qtyUnitDescTripleNext.precio_unitario,
      descuento: qtyUnitDescTripleNext.descuento,
      subtotal: qtyUnitDescTripleNext.subtotal,
    });

    idx += 2;
    continue;
  }

  const codeQtyUnitDescTriple = parseCodeQtyUnitDescriptionAndTripleLine(line);
    if (codeQtyUnitDescTriple) {
      const codigoFinal =
      shouldPromoteDescriptionAsCode(
        codeQtyUnitDescTriple.codigo,
        codeQtyUnitDescTriple.descripcion
      )
        ? codeQtyUnitDescTriple.descripcion
        : codeQtyUnitDescTriple.codigo;

      const unidadNorm = mapUnidadNorm(codeQtyUnitDescTriple.unidad);

      items.push({
        codigo: codigoFinal,
        cantidad: codeQtyUnitDescTriple.cantidad,
        unidad: unidadNorm,
        tipo_producto: deriveTipoProducto(unidadNorm),
        descripcion: codeQtyUnitDescTriple.descripcion,
        precio_unitario: codeQtyUnitDescTriple.precio_unitario,
        descuento: codeQtyUnitDescTriple.descuento,
        subtotal: codeQtyUnitDescTriple.subtotal,
      });
      idx += 1;
      continue;
    }

  const codeWithSpacesQtyUnit = parseCodeWithSpacesQtyUnitLine(line);
  if (
    codeWithSpacesQtyUnit &&
    next &&
    (parseAmountTripleLine(next2) || parseAmountQuadLine(next2))
  ) {
    const codigo = codeWithSpacesQtyUnit.codigo;
    const cantidad = codeWithSpacesQtyUnit.cantidad;
    const unidad = codeWithSpacesQtyUnit.unidad;
    const descripcion = normalizeSpaces(next);
    const tail = parseAmountQuadLine(next2) || parseAmountTripleLine(next2);

    const codigoFinal =
    shouldPromoteDescriptionAsCode(codigo, descripcion)
      ? descripcion
      : codigo;

    const unidadNorm = mapUnidadNorm(unidad);

    items.push({
      codigo: codigoFinal,
      cantidad,
      unidad: unidadNorm,
      tipo_producto: deriveTipoProducto(unidadNorm),
      descripcion,
      precio_unitario: tail.precio_unitario,
      descuento: tail.descuento,
      subtotal: tail.subtotal,
    });

    idx += 3;
    continue;
  }

  const codeTextQtyUnit = parseCodeTextQtyUnitLine(line);
    if (codeTextQtyUnit) {
      codigo = codeTextQtyUnit.codigo;
      cantidad = codeTextQtyUnit.cantidad;
      unidad = codeTextQtyUnit.unidad;

      idx += 1;

      const descripcionParts = [];
      let tail = null;

      while (idx < itemLines.length) {
        const currentLine = itemLines[idx];
        const nextLine = itemLines[idx + 1];

        const quad = parseAmountQuadLine(currentLine);
        if (quad) {
          tail = {
            precio_unitario: quad.precio_unitario,
            descuento: quad.descuento,
            subtotal: quad.subtotal,
          };
          idx += 1;
          break;
        }

        if (idx + 1 < itemLines.length) {
          const combined = `${currentLine} ${nextLine}`;
          const quadCombined = parseAmountQuadLine(combined);

          if (quadCombined) {
            tail = {
              precio_unitario: quadCombined.precio_unitario,
              descuento: quadCombined.descuento,
              subtotal: quadCombined.subtotal,
            };
            idx += 2;
            break;
          }
        }

        const triple = parseAmountTripleLine(currentLine);
        if (triple) {
          tail = triple;
          idx += 1;
          break;
        }

        // CASO 1: triple puro dividido en 2 líneas
        if (idx + 1 < itemLines.length) {
          const combined = `${currentLine} ${nextLine}`;
          const quadCombined = parseAmountQuadLine(combined);
          if (quadCombined) {
            tail = {
              precio_unitario: quadCombined.precio_unitario,
              descuento: quadCombined.descuento,
              subtotal: quadCombined.subtotal,
            };
            idx += 2;
            break;
          }

          const tripleCombined = parseAmountTripleLine(combined);
          if (tripleCombined) {
            tail = tripleCombined;
            idx += 2;
            break;
          }
        }

        // CASO 2: descripción + triple completo en una línea
        const descTriple = parseDescriptionAndTripleLine(currentLine);
        if (descTriple) {
          if (descTriple.descripcion_extra) {
            descripcionParts.push(descTriple.descripcion_extra);
          }

          tail = {
            precio_unitario: descTriple.precio_unitario,
            descuento: descTriple.descuento,
            subtotal: descTriple.subtotal,
          };
          idx += 1;
          break;
        }

        // CASO 3: descripción + triple dividido en 2 líneas
        if (idx + 1 < itemLines.length) {
          const brokenDescTriple = parseDescriptionAndBrokenTripleLines(currentLine, nextLine);

          if (brokenDescTriple) {
            if (brokenDescTriple.descripcion_extra) {
              descripcionParts.push(brokenDescTriple.descripcion_extra);
            }

            tail = {
              precio_unitario: brokenDescTriple.precio_unitario,
              descuento: brokenDescTriple.descuento,
              subtotal: brokenDescTriple.subtotal,
            };
            idx += 2;
            break;
          }
        }

        descripcionParts.push(currentLine);
        idx += 1;
      }

      if (!tail) {
        continue;
      }

      const descripcion = normalizeSpaces(descripcionParts.join(' '));
      const codigoFinal = codigo;

      const unidadNorm = mapUnidadNorm(unidad);

      items.push({
        codigo: codigoFinal,
        cantidad,
        unidad: unidadNorm,
        tipo_producto: deriveTipoProducto(unidadNorm),
        descripcion,
        precio_unitario: tail.precio_unitario,
        descuento: tail.descuento,
        subtotal: tail.subtotal,
      });

      continue;
    }


    const codeQtyUnitDesc = parseCodeQtyUnitDescriptionLine(line);
    if (codeQtyUnitDesc) {
      codigo = codeQtyUnitDesc.codigo;
      cantidad = codeQtyUnitDesc.cantidad;
      unidad = codeQtyUnitDesc.unidad;

      idx += 1;

      const descripcionParts = [codeQtyUnitDesc.descripcion];
      let tail = null;

      while (idx < itemLines.length) {
        const currentLine = itemLines[idx];

        const quad = parseAmountQuadLine(currentLine);
        if (quad) {
          tail = {
            precio_unitario: quad.precio_unitario,
            descuento: quad.descuento,
            subtotal: quad.subtotal,
          };
          idx += 1;
          break;
        }

        const triple = parseAmountTripleLine(currentLine);
        if (triple) {
          tail = triple;
          idx += 1;
          break;
        }

        const descTriple = parseDescriptionAndTripleLine(currentLine);
        if (descTriple) {
          if (descTriple.descripcion_extra) {
            descripcionParts.push(descTriple.descripcion_extra);
          }

          tail = {
            precio_unitario: descTriple.precio_unitario,
            descuento: descTriple.descuento,
            subtotal: descTriple.subtotal,
          };
          idx += 1;
          break;
        }

        descripcionParts.push(currentLine);
        idx += 1;
      }

      if (!tail) {
        continue;
      }

      const descripcionFinal = normalizeSpaces(descripcionParts.join(' '));
      const codigoFinal =
      shouldPromoteDescriptionAsCode(codigo, descripcionFinal)
        ? descripcionFinal
        : codigo;

      const unidadNorm = mapUnidadNorm(unidad);

      items.push({
        codigo: codigoFinal,
        cantidad,
        unidad: unidadNorm,
        tipo_producto: deriveTipoProducto(unidadNorm),
        descripcion: descripcionFinal,
        precio_unitario: tail.precio_unitario,
        descuento: tail.descuento,
        subtotal: tail.subtotal,
      });

      continue;
    }

    const qtyAhead = findQtyUnitAhead(itemLines, idx, 3);

  // Caso nuevo:
  // CODIGO / inicio del producto
  // DESCRIPCIÓN 1
  // DESCRIPCIÓN 2
  // 1.00 Piezas
  // DESCRIPCIÓN FINAL
  // DESCRIPCIÓN + 3 MONTOS
  if (
    (isCodeLike(line) || isCodeLikeWithSpaces(line)) &&
    qtyAhead &&
    qtyAhead.index > idx + 1
  ) {
    codigo = normalizeSpaces(
      itemLines.slice(idx, qtyAhead.index).join(' ')
    );
    cantidad = qtyAhead.cantidad;
    unidad = qtyAhead.unidad;
    idx = qtyAhead.index + 1;
  } else {
    // Caso A:
    // CODIGO 1.00 Piezas
    let matchInline = (line || '').match(
      new RegExp(`^([A-Z0-9\\/\\.\\-',]+)\\s+(${NUM_PATTERN})\\s+(${UNIT_PATTERN})$`, 'i')
    );

    let matchCodeQty = (line || '').match(
      new RegExp(`^([A-Z0-9\\/\\.\\-',]+)\\s+(${NUM_PATTERN})$`, 'i')
    );

    const fragmentQtyUnit = parseCodeFragmentQtyUnitLine(next);

    if (
      isCodeLike(line) &&
      fragmentQtyUnit
    ) {
      codigo = normalizeSpaces(`${line}${fragmentQtyUnit.fragmento_codigo}`).replace(/\s+/g, '');
      cantidad = fragmentQtyUnit.cantidad;
      unidad = fragmentQtyUnit.unidad;
      idx += 2;
    } else if (matchInline) {
      codigo = normalizeSpaces(matchInline[1]).replace(/\s+/g, '');
      cantidad = parseAmount(matchInline[2]);
      unidad = normalizeSpaces(matchInline[3]);
      idx += 1;
    } else if (
      matchCodeQty &&
      parseUnitOnlyLine(next)
    ) {
      // Caso A2:
      // CODIGO 1.00
      // Piezas
      codigo = normalizeSpaces(matchCodeQty[1]).replace(/\s+/g, '');
      cantidad = parseAmount(matchCodeQty[2]);
      unidad = parseUnitOnlyLine(next);
      idx += 2;
    } else if (
      matchCodeQty &&
      parseParentesisUnidadLine(next)
    ) {
      // Caso A2b:
      // CODIGO 1.00
      // (Bienes) o (Servicios)
      codigo = normalizeSpaces(matchCodeQty[1]).replace(/\s+/g, '');
      cantidad = parseAmount(matchCodeQty[2]);
      unidad = parseParentesisUnidadLine(next);
      idx += 2;
    } else if ((isCodeLike(line) || isCodeLikeWithSpaces(line)) && parseQtyUnitLine(next)) {
      // Caso B:
      // CODIGO
      // 1.00 Piezas
      codigo = normalizeSpaces(line);
      const qtyUnit = parseQtyUnitLine(next);
      cantidad = qtyUnit.cantidad;
      unidad = qtyUnit.unidad;
      idx += 2;
    } else if (
      (isCodeLike(line) || isCodeLikeWithSpaces(line)) &&
      parseAmountOnlyLine(next) !== null &&
      parseUnitOnlyLine(next2)
    ) {
      // Caso C:
      // CODIGO
      // 1.00
      // Piezas
      codigo = normalizeSpaces(line);
      cantidad = parseAmountOnlyLine(next);
      unidad = parseUnitOnlyLine(next2);
      idx += 3;

          } else if (
      (isCodeLike(line) || isCodeLikeWithSpaces(line)) &&
      parseAmountOnlyLine(next) !== null &&
      parseParentesisUnidadLine(next2)
    ) {
      // Caso C2:
      // CODIGO
      // 1
      // (Bienes)
      codigo = normalizeSpaces(line);
      cantidad = parseAmountOnlyLine(next);
      unidad = parseParentesisUnidadLine(next2);
      idx += 3;
    } else if (
      (isCodeLike(line) || isCodeLikeWithSpaces(line)) &&
      parseAmountOnlyLine(next) !== null &&
      /^Unidad\s*\((Bienes|Servicios)\)$/i.test(next2)
    ) {
      // Caso C3:
      // CODIGO
      // 1
      // Unidad (Bienes)
      codigo = normalizeSpaces(line);
      cantidad = parseAmountOnlyLine(next);
      unidad = normalizeSpaces(next2);
      idx += 3;


    } else {
      idx += 1;
      continue;
    }
  }

  // Recolectar descripción hasta encontrar línea de 3 montos
  const descripcionParts = [];
  let tail = null;

  while (idx < itemLines.length) {
    const currentLine = itemLines[idx];
    const nextLine = itemLines[idx + 1];

    const quad = parseAmountQuadLine(currentLine);
    if (quad) {
      tail = {
        precio_unitario: quad.precio_unitario,
        descuento: quad.descuento,
        subtotal: quad.subtotal,
      };
      idx += 1;
      break;
    }

    if (idx + 1 < itemLines.length) {
      const combined = `${currentLine} ${nextLine}`;
      const quadCombined = parseAmountQuadLine(combined);

      if (quadCombined) {
        tail = {
          precio_unitario: quadCombined.precio_unitario,
          descuento: quadCombined.descuento,
          subtotal: quadCombined.subtotal,
        };
        idx += 2;
        break;
      }
    }

    const triple = parseAmountTripleLine(currentLine);
    if (triple) {
      tail = triple;
      idx += 1;
      break;
    }

    // CASO 1: triple puro dividido en 2 líneas
    if (idx + 1 < itemLines.length) {
      const combined = `${currentLine} ${nextLine}`;
      const quadCombined = parseAmountQuadLine(combined);
      if (quadCombined) {
        tail = {
          precio_unitario: quadCombined.precio_unitario,
          descuento: quadCombined.descuento,
          subtotal: quadCombined.subtotal,
        };
        idx += 2;
        break;
      }

      const tripleCombined = parseAmountTripleLine(combined);
      if (tripleCombined) {
        tail = tripleCombined;
        idx += 2;
        break;
      }
    }

    // CASO 2: descripción + triple completo en una línea
    const descTriple = parseDescriptionAndTripleLine(currentLine);
    if (descTriple) {
      if (descTriple.descripcion_extra) {
        descripcionParts.push(descTriple.descripcion_extra);
      }

      tail = {
        precio_unitario: descTriple.precio_unitario,
        descuento: descTriple.descuento,
        subtotal: descTriple.subtotal,
      };
      idx += 1;
      break;
    }

    // CASO 3: descripción + triple dividido en 2 líneas
    if (idx + 1 < itemLines.length) {
      const brokenDescTriple = parseDescriptionAndBrokenTripleLines(currentLine, nextLine);

      if (brokenDescTriple) {
        if (brokenDescTriple.descripcion_extra) {
          descripcionParts.push(brokenDescTriple.descripcion_extra);
        }

        tail = {
          precio_unitario: brokenDescTriple.precio_unitario,
          descuento: brokenDescTriple.descuento,
          subtotal: brokenDescTriple.subtotal,
        };
        idx += 2;
        break;
      }
    }

    descripcionParts.push(currentLine);
    idx += 1;
  }

  if (!tail) {
    continue;
  }

  const descripcion = normalizeSpaces(descripcionParts.join(' '));
  const codigoFinal =
    shouldPromoteDescriptionAsCode(codigo, descripcion)
      ? descripcion
      : codigo;

  const unidadNorm = mapUnidadNorm(unidad);

  items.push({
    codigo: codigoFinal,
    cantidad,
    unidad: unidadNorm,
    tipo_producto: deriveTipoProducto(unidadNorm),
    descripcion,
    precio_unitario: tail.precio_unitario,
    descuento: tail.descuento,
    subtotal: tail.subtotal,
  });
}

