function isCodeLike(line) {
  const value = normalizeSpaces(line || '');
  return /^[A-Z0-9\/.\-',]+$/i.test(value) && /[A-Z]/i.test(value);
}

function isCodeLikeWithSpaces(line) {
  const value = normalizeSpaces(line);
  if (!value) return false;

  if (isHeaderNoiseLine(value)) return false;

  // Permitir letras acentuadas y Ñ/Ü
  if (!/^[A-Z0-9ÁÉÍÓÚÑÜ\/.\-',\s]+$/i.test(value)) return false;

  const tokens = value.split(/\s+/);

  if (tokens.length < 2 || tokens.length > 6) return false;

  const hasLetter = tokens.some(t => /[A-ZÁÉÍÓÚÑÜ]/i.test(t));
  const hasCodeSignal = tokens.some(t => /[0-9\/.\-']/.test(t));

  return hasLetter && hasCodeSignal;
}

function isMergeableCodeFragment(line) {
  const value = normalizeSpaces(line);
  if (!value) return false;

  if (isHeaderNoiseLine(value)) return false;
  if (!/^[A-Z0-9ÁÉÍÓÚÑÜ\/.\-',\s]+$/i.test(value)) return false;

  if (
    parseQtyUnitLine(value) ||
    parseAmountOnlyLine(value) !== null ||
    parseUnitOnlyLine(value) ||
    parseAmountTripleLine(value) ||
    parseDescriptionAndTripleLine(value) ||
    parseFullInlineItem(value) ||
    parseSimpleInlineItem(value) ||
    parseCodeQtyUnitDescriptionLine(value) ||
    parseCodeQtyUnitDescriptionAndTripleLine(value) ||
    parseCodeFragmentQtyUnitLine(value) ||
    parseCodeWithSpacesQtyUnitLine(value) ||
    parseCodeTextQtyUnitLine(value)
  ) {
    return false;
  }

  const tokens = value.split(/\s+/);

  // Permitimos hasta 3 tokens para casos como:
  // ETBH005.AZUL
  // TAQUIÑA.M
  // o TOPO GRIS CL.XL
  if (tokens.length > 3) return false;

  // Si son solo palabras puras sin puntos ni números, no fusionar
  const hasDigit = /[0-9]/.test(value);
  const hasDotSlashHyphen = /[./\-']/.test(value);
  const hasLetter = /[A-ZÁÉÍÓÚÑÜ]/i.test(value);

  if (!hasLetter) return false;
  if (!hasDigit && !hasDotSlashHyphen) return false;

  return true;
}

function hasCodeSignal(line) {
  return /[0-9\/.\-']/.test(normalizeSpaces(line || ''));
}

function isUpperTextFragment(line) {
  const value = normalizeSpaces(line);
  if (!value) return false;
  if (isHeaderNoiseLine(value)) return false;

  // Permitir Ñ y vocales acentuadas
  if (!/^[A-ZÁÉÍÓÚÑÜ.\-\/'\s]+$/i.test(value)) return false;

  const tokens = value.split(/\s+/);

  if (tokens.length < 1 || tokens.length > 5) return false;

  return /[A-ZÁÉÍÓÚÑÜ]/i.test(value);
}

function isNumericCodeSuffix(line) {
  const value = normalizeSpaces(line || '');

  return (
    /^[0-9]{1,3}$/.test(value) ||     // 4, 12, 123
    /^\.[0-9]{1,3}$/.test(value) ||   // .12, .6
    /^\.[A-Z0-9]{1,4}$/i.test(value)  // .XS, .M, .12
  );
}

function isCodeContinuationFragment(line) {
  const value = normalizeSpaces(line || '');
  if (!value) return false;

  // Permitir fragmentos tipo:
  // SCURO.S
  // NRY.L
  // .12
  // .XS
  // AZUL.M
  if (!/^[A-Z0-9\/.\-',]+$/i.test(value)) return false;

  // No debe ser una unidad, cantidad o línea de montos completas
  if (
    parseQtyUnitLine(value) ||
    parseAmountOnlyLine(value) !== null ||
    parseUnitOnlyLine(value) ||
    parseAmountTripleLine(value)
  ) {
    return false;
  }

  // Aceptar específicamente fragmentos que empiezan con punto
  if (/^\.[A-Z0-9]{1,4}$/i.test(value)) {
    return true;
  }

  return true;
}

function joinCodeParts(left, right) {
  const a = normalizeSpaces(left || '');
  const b = normalizeSpaces(right || '');

  if (!a) return b;
  if (!b) return a;

  // Si el primer fragmento termina con punto, slash, guion o apóstrofe, unir sin espacio
  if (/[.,/\-']$/.test(a)) {
    return `${a}${b}`;
  }

  // Si el segundo fragmento parece continuación técnica del código, unir sin espacio
  if (isCodeContinuationFragment(b)) {
    return `${a}${b}`;
  }

  // En otros casos, unir con espacio
  return `${a} ${b}`;
}

function extractLeadingCode(value) {
  const text = normalizeSpaces(value || '');
  if (!text) return text;

  const firstToken = text.split(/\s+/)[0] || '';

  // Si el primer token parece un código real, usarlo
  if (/^[A-Z0-9][A-Z0-9\/.\-',]*$/i.test(firstToken) && /[0-9]/.test(firstToken)) {
    return firstToken;
  }

  return text;
}

function isSuspiciousCode(code) {
  const value = normalizeSpaces(code || '');
  if (!value) return true;

  if (value.length < 4) return true;
  if (!/[A-Z]/i.test(value)) return true;

  const tokens = value.split(/\s+/);

  // Si no tiene dígitos, es sospechoso aunque tenga puntos
  if (!/[0-9]/.test(value)) return true;

  // Si parece puro texto de color/talla sin prefijo real de código
  const commonWords = ['NEGRO', 'BLANCO', 'ROJO', 'AZUL', 'VERDE', 'GRIS', 'TOPO', 'XL', 'L', 'M', 'S'];
  const upperTokens = tokens.map(t => t.toUpperCase().replace(/[^A-Z0-9]/g, ''));
  const allCommon = upperTokens.every(t => commonWords.includes(t) || /^[A-Z]+$/.test(t));

  if (allCommon && !/[0-9]/.test(value)) return true;

  return false;
}

function parseQtyUnitLine(line) {
  const match = (line || '').match(
    new RegExp(`^(${NUM_PATTERN})\\s+(${UNIT_PATTERN})$`, 'i')
  );
