}

function findQtyUnitAhead(lines, startIndex, maxLookahead = 3) {
  for (let offset = 1; offset <= maxLookahead; offset++) {
    const candidate = lines[startIndex + offset];
    const parsed = parseQtyUnitLine(candidate);

    if (parsed) {
      return {
        index: startIndex + offset,
        cantidad: parsed.cantidad,
        unidad: parsed.unidad,
      };
    }
  }

  return null;
}

function parseAmountOnlyLine(line) {
  const match = (line || '').match(new RegExp(`^(${NUM_PATTERN})$`));
