      value === 'CANTIDAD' ||
      value === 'UNIDAD' ||
      value === 'DE' ||
      value === 'MEDIDA' ||
      value === 'UNIDADDE' ||
      value === 'UNIDADDEMEDIDA' ||
      value === 'DESCRIPCION' ||
      value === 'PRECIO' ||
      value === 'UNITARIO' ||
      value === 'PRECIOUNITARIO' ||
      value === 'DESCUENTO' ||
      value === 'SUBTOTAL'
    );
  }

  return (
    value === 'CODIGO' ||
    value === 'PRODUCTO' ||
    value === '/' ||
    value === 'PRODUCTO/' ||
    value === 'SERVICIO' ||
    value === 'CANTIDAD' ||
    value === 'UNIDAD' ||
    value === 'DE' ||
