// ===== ITEMS TIPO C =====

function extractItemsBlockTipoC(source) {
  const start =
  source.match(/DETALLE\s*\n\s*SUBTOTAL/i) ||
  source.match(/DETALLE/i);
  if (!start) return '';

  const tail = source.slice(start.index + start[0].length);

  const end = tail.match(/\nSUBTOTAL\s+(?:Bs\.?|[0-9])/i);
  if (!end) return tail;

  return tail.slice(0, end.index);
}

function isUnitLineTipoC(line) {
  const value = normalizeSpaces(line)
    .toUpperCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');

  return [
    'PIEZA',
    'PIEZAS',
    'PIE',
    'PIES',
    'KG',
    'KGS',
    'KILOGRAMO',
    'KILOGRAMOS',
    'UNIDAD',
    'UNIDADES',
    'METRO',
    'METROS',
    'JUEGO',
    'JUEGOS',
    'DOCENA',
    'DOCENAS'
  ].includes(value) || /^UNIDAD\s+DE\s+MEDIDA\s*:/i.test(line);
}

const QTY_PATTERN_C = '[0-9]+(?:[.,][0-9]{1,4})?';
const MONEY_PATTERN_C = '[0-9][0-9.,]*(?:[.,][0-9]{2})';
const TOLERANCIA = 0.05;

// REFORZADO: grupos numéricos SIN \s para no fusionar descuento + subtotal
function isCalcLineTipoC(line) {
  const value = normalizeSpaces(line);
  const re = new RegExp(
    `^(${QTY_PATTERN_C})\\s*X\\s*(${MONEY_PATTERN_C})\\s*-\\s*(${MONEY_PATTERN_C})(?:\\s+(${MONEY_PATTERN_C}))?$`,
    'i'
  );

  return re.test(value);
}

function isMoneyOnlyLineTipoC(line) {
  const value = normalizeSpaces(line);
  const re = new RegExp(`^(${MONEY_PATTERN_C})$`, 'i');
  return re.test(value);
}

function isShortCodeSuffixPart(part) {
  const value = normalizeSpaces(part || '').toUpperCase();

  if (!value) return false;

  // Casos como: 4, 12, A, B2, XL, XS
  return /^[A-Z0-9]{1,4}$/.test(value);
}

function splitCodeDescTipoC(line) {
  const value = normalizeSpaces(line || '');
  if (!value || !value.includes('-')) return null;

  const parts = value.split('-').map(p => normalizeSpaces(p)).filter(Boolean);
  if (parts.length < 2) return null;

  // Caso normal: CODIGO-DESCRIPCION
  // Caso especial: 4162-4-PIJAMA...
  let codeParts = [parts[0]];
  let descStartIndex = 1;

  // Si el segundo segmento parece sufijo corto de código, lo agregamos al código
  if (parts.length >= 3 && isShortCodeSuffixPart(parts[1])) {
    codeParts.push(parts[1]);
    descStartIndex = 2;
  }

  const codigo = codeParts.join('-').replace(/\s+/g, '');
  const descripcion = parts.slice(descStartIndex).join(' - ').trim();

  if (!codigo || !descripcion) return null;

  return { codigo, descripcion };
}

function parseItemsTipoC(block) {
  const lines = block
    .split('\n')
    .map(l => normalizeSpaces(l))
    .filter(Boolean);

  const result = [];
  let i = 0;

  while (i < lines.length) {
    const firstLine = lines[i];

    // Debe empezar con CODIGO-DESCRIPCION
    const codeDescParsed = splitCodeDescTipoC(firstLine);
    if (!codeDescParsed) {
      i += 1;
      continue;
    }

    const codigo = codeDescParsed.codigo;
    const descripcionParts = [normalizeSpaces(codeDescParsed.descripcion)];

    let unidadRaw = null;
    let cantidad = null;
    let precio_unitario = null;
    let descuento = null;
    let subtotal_item = null;

    let j = i + 1;

    // 1) Capturar líneas extra de descripción hasta encontrar unidad
    while (j < lines.length && !isUnitLineTipoC(lines[j]) && !isCalcLineTipoC(lines[j])) {
      descripcionParts.push(lines[j]);
      j += 1;
    }

    // 2) Capturar unidad
    if (j < lines.length && isUnitLineTipoC(lines[j])) {
      const unitLine = lines[j];
      const unitLabelMatch = unitLine.match(/Unidad\s+de\s+Medida\s*:\s*(.+)/i);

      if (unitLabelMatch) {
        unidadRaw = normalizeSpaces(unitLabelMatch[1]);
      } else {
        unidadRaw = normalizeSpaces(unitLine);
      }

      j += 1;
    }

    // 3) Capturar línea de cálculo (REFORZADO: grupos numéricos sin \s)
    while (j < lines.length) {
      const calcLine = normalizeSpaces(lines[j]);

      const calcRe = new RegExp(
        `^(${QTY_PATTERN_C})\\s*X\\s*(${MONEY_PATTERN_C})\\s*-\\s*(${MONEY_PATTERN_C})(?:\\s+(${MONEY_PATTERN_C}))?$`,
        'i'
      );

      const calcMatch = calcLine.match(calcRe);

      if (calcMatch) {
        cantidad = parseAmount(calcMatch[1]);
        precio_unitario = parseAmount(calcMatch[2]);
        descuento = parseAmount(calcMatch[3]);

        // subtotal puede venir en la misma línea o en la siguiente
        if (calcMatch[4]) {
          subtotal_item = parseAmount(calcMatch[4]);
          j += 1;
        } else if (j + 1 < lines.length && isMoneyOnlyLineTipoC(lines[j + 1])) {
          subtotal_item = parseAmount(lines[j + 1]);
          j += 2;
        } else {
          j += 1;
        }

        break;
      }

      j += 1;
    }

    const descripcion = normalizeSpaces(descripcionParts.join(' '));
    const unidadNorm = mapUnidadNorm(unidadRaw);

    if (
      codigo &&
      descripcion &&
      cantidad !== null &&
      precio_unitario !== null &&
      descuento !== null &&
      subtotal_item !== null
    ) {
      const subtotalCalculado = Number(((cantidad || 0) * (precio_unitario || 0) - (descuento || 0)).toFixed(2));
      const subtotalOk =
        subtotal_item !== null &&
        Math.abs(Number(subtotalCalculado) - Number(subtotal_item)) <= TOLERANCIA;
      result.push({
        codigo,
        cantidad,
        unidad: unidadNorm,
        tipo_producto: deriveTipoProducto(unidadNorm),
        descripcion,
        precio_unitario,
        descuento,
        subtotal: subtotal_item,
        subtotal_calculado: subtotalCalculado,
        subtotal_ok: subtotalOk,
      });
    }

    i = Math.max(j, i + 1);
  }

  return result;
}

